import {
    Component,
    ElementRef,
    EventEmitter,
    Input,
    OnDestroy,
    OnInit,
    Output,
    ViewChild,
} from '@angular/core';
import { CommonModule, CurrencyPipe } from '@angular/common';
import { TableModule } from 'primeng/table';
import { ButtonModule } from 'primeng/button';
import { DialogModule } from 'primeng/dialog';
import { InputTextModule } from 'primeng/inputtext';
import { StockService } from 'src/app/stock/stock.service';
import { Subscription } from 'rxjs';
import { Products } from 'src/app/core/interfaces/stock.interface';

@Component({
    selector: 'products-dialog',
    standalone: true,
    imports: [
        TableModule,
        ButtonModule,
        DialogModule,
        CurrencyPipe,
        CommonModule,
        InputTextModule,
    ],
    templateUrl: './products-dialog.component.html',
    styleUrl: './products-dialog.component.scss',
})
export class ProductsDialogComponent implements OnInit, OnDestroy {
    @ViewChild('tableSearch') tableSearch!: ElementRef;

    @Input() visible: boolean = false;

    @Input() selectionMode: any = 'multiple';

    @Output() onSubmit = new EventEmitter<any>();
    @Output() onHide = new EventEmitter<boolean>();

    constructor(private stockService: StockService) {}

    subscriptions = new Subscription();
    products: Products[];
    selectedProducts: any = [];

    ngOnInit(): void {
        this.subscriptions.add(
            this.stockService.items.subscribe((res) => {
                this.products = res;
            })
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    // submit
    submitProducts() {
        this.onSubmit.emit(this.selectedProducts);
        this.closeDialog();
    }

    // closeDialog
    closeDialog() {
        this.selectedProducts = [];
        this.onHide.emit(false);
    }

    print() {
        window.print();
    }

    selectInput() {
        this.tableSearch.nativeElement.select();
    }
}
